def extract_sentence_boundaries(text):
    # Split the text into sentences
    sentence_list = text.replace("?", ".").replace("!", ".").split(".")
    # Remove leading/trailing whitespaces and empty strings
    sentence_list = [sentence.strip() for sentence in sentence_list if sentence.strip()]
    # Identify sentence boundaries
    sentence_boundaries = []
    for i in range(len(sentence_list)):
        if i == 0:
            sentence_boundaries.append((0, len(sentence_list[i])))
        else:
            sentence_boundaries.append((sentence_boundaries[i-1][1] + 1, sentence_boundaries[i-1][1] + len(sentence_list[i]) + 1))
