def calculate_next_quarter(date_string: str) -> str:
    from datetime import datetime, timedelta
    date = datetime.strptime(date_string, "%Y-%m-%d")
    quarter = (date.month - 1) // 3 + 1
    if quarter == 4:
        next_quarter_date = date.replace(year=date.year + 1, month=1, day=1)
    else:
        next_quarter_date = date.replace(month=(quarter * 3) + 1, day=1)
    next_quarter_date = next_quarter_date - timedelta(days=1)
    return next_quarter_date.strftime("%Y-%m-%d")

